userscript.function:

    		let formData = $formObj.getFormData();

    		if(Sepoa.params.useType == Sepoa.config.get("sepoa.secl.req.seal.contract.use.number")){
    			let contractPetition = formData.CONTRACT_PETITION;
	    		if(contractPetition == null || contractPetition == ""){
	    			Alert("계약체결품의서를 선택해주세요.");
	    			return;
	    		}
	    		if(contractPetition == '2'){
	    			let reason = formData.NO_PETITION_REASON;
	    			if(reason == null || reason == "") {
		    			Alert("계약체결품의서 선택 사유를 입력해주세요.");
		    			return;
	    			}
	    		}

	    		let legalCheck = formData.LEGAL_CHECK;
	    		if(legalCheck == null || legalCheck == ""){
	    			Alert("법무검토를 선택해주세요.");
	    			return;
	    		}
	    		if(legalCheck == '2'){
	    			let reason = formData.LEGAL_CHECK_REASON;
	    			if(reason == null || reason == "") {
		    			Alert("미반영사유를 입력해주세요.");
		    			return;
	    			}
	    		}

	    		let contractType = formData.CONTRACT_TYPE;
	    		if(contractType == null || contractType == ""){
	    			Alert("계약유형을 선택해주세요.");
	    			return;
	    		}

	    		let contractTarget = formData.CONTRACT_TARGET;
	    		if(contractType == '1' && contractTarget == null) {
	    			Alert("계약대상을 선택해주세요.");
	 				return;
				}

				if(contractType == '1') {
					let contractAmount = formData.CONTRACT_AMOUNT;
					if(contractAmount == null || contractAmount == "") {
						Alert("계약금액을 입력해주세요.");
		    			return;
					}
				}

				if(contractType == '1') {
					let contractFrom = formData.CONTRACT_FROM;
					let contractTo = formData.CONTRACT_TO;
					if( (contractFrom == null || contractFrom == "") || (contractTo == null || contractTo == "") ) {
						Alert("계약기간을 입력해주세요.");
		    			return;
					}
				}

				if(contractType == '1' && contractTarget == '3') {
					let siteManual = formData.SITE_MANUAL;
					if(siteManual == null || siteManual == "") {
						Alert("현장설명서를 선택해주세요");
						return;				
					}
				}

				if(contractType == '1' && contractTarget == '3'){
					let taskDirections = formData.TASK_DIRECTIONS;
					if(taskDirections == null || taskDirections == "") {
						Alert("과업지시서를 선택해주세요");
	   					return;
					}
				} 

	    		let changeAmount =  formData.CHANGE_AMOUNT;
	    		if(contractType == '2' && (changeAmount == null || changeAmount == "") ) {
	    			Alert("금액변경을 선택해주세요.");
	   				return;
	    		}

	    		if(contractType == '2' && changeAmount == '1') {
	    			let oldContAmount = formData.OLD_CONTRACT_AMOUNT;
	    			let newContAmount = formData.NEW_CONTRACT_AMOUNT;

	    			if( (oldContAmount == null || oldContAmount == "") || (newContAmount == null || newContAmount == "") ) {
	    				Alert("금액변경의 내용을 입력해주세요.");
	   					return;
	    			} 

	    		}

	    		let changeContFrom = formData.CHANGE_CONT_FROM;
	    		if(contractType == '2' && (changeContFrom == null || changeContFrom == "") ) {
	    			Alert("기간변경을 선택해주세요.");
	   				return;
	    		}

	    		if(contractType == '2' && changeContFrom == '1') {
	    			let oldContFrom = formData.OLD_CONTRACT_FROM;
	    			let oldcontTo = formData.OLD_CONTRACT_TO;
	    			let newContFrom = formData.NEW_CONTRACT_FROM;
	    			let newContTo = formData.NEW_CONTRACT_TO;

	    			if( (oldContFrom == null || oldContFrom == "") || (oldcontTo == null || oldcontTo == "") || (newContFrom == null || newContFrom == "") || (newContTo == null || newContTo == "") ) {
				    	Alert("기간변경을 내용을 입력해주세요.");
	   					return;		
	    			}
	    		}

	    		let contConditionalChange = formData.CONTRACT_CONDITIONAL_CHANGE;
	    		if(contractType == '2' && (contConditionalChange == null || contConditionalChange == "")) {
	    			Alert("계약 조건 변경을 입력해주세요.");
	    			return;
	    		}

	    		let contConditionalChangeReason = formData.CONTRACT_CONDITIONAL_CHANGE_REASON;
	    		if(contractType == '2' && (contConditionalChangeReason == null || contConditionalChangeReason == "")) {
	    			Alert("변경사유를 입력해주세요.");
	    			return;
	    		}
    		}

    		let contractObj = formData;
    		if($formObj.getValue("ATTACH_DOC") && $formObj.getValue("ATTACH_DOC") != ""){
    			let fileData = Object.values($formObj.getForm(Object.keys($formObj._formList)[0]).getVault("ATTACH_DOC").file_data);
    			contractObj["FILE_LIST"] = fileData;
    		}

    		if (Sepoa.params && Sepoa.params.callback) {
    			let convertTarget = ['NEW_CONTRACT_TO', 'NEW_CONTRACT_FROM', 'OLD_CONTRACT_TO', 'OLD_CONTRACT_FROM', 'CONTRACT_TO', 'CONTRACT_FROM'];
    			for(let i in convertTarget) {
    				let key = convertTarget[i];
    				contractObj[key] = $formObj.getValue(key);
    			}
				Sepoa.params.callback(contractObj);
			}

			selfObj.close();


            var curreny = [
