            $formObj = new SepoaMultiDhtmlXFormObject(container, 'contractInfoForm', [formOption], true);
            $formObj.attachEvent("onChange", initEvent);

            if(Sepoa.params && Sepoa.params.DATA && Object.keys(Sepoa.params.DATA).length > 0) {
            	//$formObj.dataMapper(Sepoa.params.DATA, "JSON");

            	let keysArr = Object.keys(Sepoa.params.DATA);
            	for(let i in keysArr) {
            		let targetKey = keysArr[i];
            		let targetValue = Sepoa.params.DATA[targetKey];
            		if(targetValue && targetValue != ''){
	            		initEvent(targetKey, targetValue);
	            		$formObj.getForm(Object.keys($formObj._formList)[0]).setItemValue(targetKey, targetValue);
            		}
