if (name == "CONTRACT_PETITION") { //계약체결품의서 radio 
    if (value == "1") { // Y일때 사유 입력란 숨기기
        $formObj.hideItem("NO_PETITION_REASON_BLOCK");
    } else { // N일때 사유 입력란 보이기
        $formObj.showItem("NO_PETITION_REASON_BLOCK");
    }
} else if (name == "LEGAL_CHECK") { //법무검토 radio
    if (value == "2") {
        $formObj.showItem("LEGAL_CHECK_REASON_BLOCK"); //일부 반영일때 미반영사유란 노출
    } else {
        $formObj.hideItem("LEGAL_CHECK_REASON_BLOCK"); //그 외 미반영사유란 숨기기
    }
} else if (name == "CONTRACT_TYPE") { //계약유형 radio
    if (value == "1") { //원계약일 때 원계약용 아이템 보이기
        $formObj.showItem("ORG_CONTRACT_TARGET_SUMMARY_BLOCK");
        $formObj.hideItem("CHANGE_CONTRACT_SUMMARY_BLOCK");
    } else { //변경계약일 때 원계약용 아이템 숨기기
        $formObj.hideItem("ORG_CONTRACT_TARGET_SUMMARY_BLOCK");
        $formObj.showItem("CHANGE_CONTRACT_SUMMARY_BLOCK");
    }
} else if (name == "CONTRACT_TARGET") { //계약대상 radio
    if (value == "3") {
        $formObj.showItem("SITE_MANUAL_BLOCK");
        $formObj.showItem("TASK_DIRECTIONS_BLOCK"); //협력업체일 때 현장설명서, 과업지시서 노출
    } else {
        $formObj.hideItem("SITE_MANUAL_BLOCK");
        $formObj.hideItem("TASK_DIRECTIONS_BLOCK"); //그 외 현장설명서, 과업지시서 숨기기
    }
} else if (name == "CHANGE_AMOUNT") { //금액 변경 radio
    if (value == "1") {
        $formObj.showItem("CONTRACT_AMOUNT_BLOCK"); //금액변경 상세 보이기
    } else {
        $formObj.hideItem("CONTRACT_AMOUNT_BLOCK"); //금액변경 상세 숨기기
    }
} else if (name == "CHANGE_CONT_FROM") { //기간변경 radio
    if (value == "1") {
        $formObj.showItem("CHANGE_CONT_FROM_DETAIL_BLOCK"); //기간변경 상세 보이기
    } else {
        $formObj.hideItem("CHANGE_CONT_FROM_DETAIL_BLOCK"); //기간변경 상세 숨기기
    }
}
